insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:multimedia-designer','AU','multimedia-designer','Multimedia Designer','OSCA','2024 v1.0','2421','AUD',false,'No statutory registration; VETASSESS 232413 and ACS 261211 migration assessment routes cover partial ANZSCO correspondences','https://www.vetassess.com.au/check-my-occupation/professional-occupations/multimedia-designer','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:multimedia-designer','2026-05-01',null,null,null,null,1852,null,null,null,null,441,'2026-05-01',-7.68,9.86,18.96,0,0,5,0,13,0,5,5,5,33,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Current OSCA 242131 Multimedia Designer is an exact canonical occupation. ABS current correspondence maps it partially to ANZSCO 2022 232413 Multimedia Designer and partially to 261211 Multimedia Specialist.','labour_scope','Primary employment, demographics and earnings remain null because no single ANZSCO labour profile represents the full current OSCA 242131 scope.','legacy_232413_context',jsonb_build_object('employment_total',4600,'part_time_share_pct',26,'female_share_pct',50,'median_age',36,'average_full_time_hours',41,'median_weekly_earnings_aud',null,'scope','Legacy JSA ANZSCO 232413 Multimedia Designer context only'),'legacy_261211_context',jsonb_build_object('employment_total',1100,'part_time_share_pct',22,'female_share_pct',18,'median_age',32,'average_full_time_hours',42,'median_weekly_earnings_aud',null,'scope','Legacy JSA ANZSCO 261211 Multimedia Specialist context only'),'vacancy_scope','Broader ANZSCO 2324 vacancies were 441 in May 2026 versus 477.66667 in May 2025, about -7.68% year on year. ANZSCO 2612 vacancies were 76.66667 versus 76, about +0.88%. Neither series receives exact vacancy intensity or trend credit.','projection_scope','Broader ANZSCO 2324 projections are +9.86% to 2030 and +18.96% to 2035; ANZSCO 2612 projections are +15.88% and +26.88%. Partial growth credit only.','shortage_note','JSA 2025 OSL records current OSCA 242131 Multimedia Designer as No Shortage nationally.','visa_basis','The current Core Skills Occupation List includes ANZSCO 232413 Multimedia Designer with VETASSESS and ANZSCO 261211 Multimedia Specialist with ACS. Because current OSCA 242131 corresponds partially to both, visa credit is reduced to partial rather than treating either route as a one-to-one match.','entry_level_basis','RMIT Bachelor of Design (Digital Media) 080226G is a direct digital-media route; UTS Bachelor of Design in Visual Communication 077339C includes digital media, motion design, interaction, UX and emerging creative technologies.','score_note','Exact current OSCA classification is preserved while statistical and migration evidence is explicitly scoped to the split ANZSCO correspondence.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
